mapper.select:
SELECT ty.id, ty.year, ty.dept_id, ty.dept_name, ty.create_user_name, ty.create_time, temp.* FROM ( SELECT metrics,main_id,staff_id,min(staff_name) AS staffName, COALESCE(SUM ( CASE WHEN month = 1 THEN value ELSE NULL END )*${multiplyNum},NULL) AS january, COALESCE(SUM ( CASE WHEN month = 1 THEN rate ELSE NULL END )*100,NULL) AS januaryRate, COALESCE(SUM ( CASE WHEN month = 2 THEN value ELSE NULL END )*${multiplyNum},NULL) AS february, COALESCE(SUM ( CASE WHEN month = 2 THEN rate ELSE NULL END )*100,NULL) AS februaryRate, COALESCE(SUM ( CASE WHEN month = 3 THEN value ELSE NULL END )*${multiplyNum},NULL) AS march, COALESCE(SUM ( CASE WHEN month = 3 THEN rate ELSE NULL END )*100,NULL) AS marchRate, COALESCE(SUM ( CASE WHEN month = 4 THEN value ELSE NULL END )*${multiplyNum},NULL) AS april, COALESCE(SUM ( CASE WHEN month = 4 THEN rate ELSE NULL END )*100,NULL) AS aprilRate, COALESCE( SUM ( CASE WHEN month = 5 THEN value ELSE NULL END )*${multiplyNum},NULL) AS may, COALESCE(SUM ( CASE WHEN month = 5 THEN rate ELSE NULL END )*100,NULL) AS mayRate, COALESCE(SUM ( CASE WHEN month = 6 THEN value ELSE NULL END )*${multiplyNum},NULL) AS june, COALESCE( SUM ( CASE WHEN month = 6 THEN rate ELSE NULL END )*100,NULL) AS juneRate, COALESCE(SUM ( CASE WHEN month = 7 THEN value ELSE NULL END )*${multiplyNum},NULL) AS july, COALESCE(SUM ( CASE WHEN month = 7 THEN rate ELSE NULL END )*100,NULL) AS julyRate, COALESCE(SUM ( CASE WHEN month = 8 THEN value ELSE NULL END ) *${multiplyNum},NULL)AS august, COALESCE(SUM ( CASE WHEN month = 8 THEN rate ELSE NULL END )*100,NULL) AS augustRate, COALESCE(SUM ( CASE WHEN month = 9 THEN value ELSE NULL END )*${multiplyNum},NULL) AS september, COALESCE(SUM ( CASE WHEN month = 9 THEN rate ELSE NULL END )*100,NULL) AS septemberRate, COALESCE(SUM ( CASE WHEN month = 10 THEN value ELSE NULL END )*${multiplyNum},NULL) AS october, COALESCE(SUM ( CASE WHEN month = 10 THEN rate ELSE NULL END )*100,NULL) AS octoberRate, COALESCE(SUM ( CASE WHEN month = 11 THEN value ELSE NULL END )*${multiplyNum},NULL) AS november, COALESCE(SUM ( CASE WHEN month = 11 THEN rate ELSE NULL END )*100,NULL) AS novemberRate, COALESCE(SUM ( CASE WHEN month = 12 THEN value ELSE NULL END )*${multiplyNum},NULL) AS december, COALESCE(SUM ( CASE WHEN month = 12 THEN rate ELSE NULL END )*100,NULL) AS decemberRate FROM bi_target_new_product_setting WHERE metrics=#{params.metrics} AND is_deleted = FALSE GROUP BY metrics,staff_id,main_id ) temp LEFT JOIN bi_target_year ty ON temp.main_id = ty.id WHERE ty.is_deleted=false
AND ty.year =#{params.year}
AND ty.dept_id =#{params.deptId}
AND temp.staffName ILIKE concat('%', #{params.name}::text ,'%')
${params.permissionSql}
ORDER BY ty.id DESC

SELECT ty.dept_id, ty.dept_name, btnps.month, SUM(btnps.value) AS value, btnps.metrics, SUM(btnps.rate) AS rate FROM bi_target_year ty INNER JOIN bi_target_new_product_setting btnps ON ty.id = btnps.main_id AND btnps.is_deleted = false WHERE ty.is_deleted = false
AND ty.year = #{params.year}
AND btnps.month = #{params.month}
AND btnps.metrics IN
#{metrics}
AND ty.dept_id IN
#{deptId}
GROUP BY ty.dept_id, ty.dept_name, btnps.month, btnps.metrics

SELECT btnps.staff_id AS userId, btnps.staff_name AS userName, btnps.month, SUM(btnps.value) AS value, btnps.metrics, SUM(btnps.rate) AS rate FROM bi_target_year ty INNER JOIN bi_target_new_product_setting btnps ON ty.id = btnps.main_id AND btnps.is_deleted = false WHERE ty.is_deleted = false
AND ty.year = #{params.year}
AND btnps.month = #{params.month}
AND btnps.metrics IN
#{metrics}
AND btnps.staff_id IN
#{userId}
GROUP BY btnps.staff_id, btnps.staff_name, btnps.month, btnps.metrics

SELECT COALESCE(sum(january)*${multiplyNum},0) AS januaryTotal, COALESCE(sum(february)*${multiplyNum},0) AS februaryTotal, COALESCE(sum(march)*${multiplyNum},0) AS marchTotal, COALESCE(sum(april)*${multiplyNum},0) AS aprilTotal, COALESCE(sum(may)*${multiplyNum},0) AS mayTotal, COALESCE(sum(june)*${multiplyNum},0) AS juneTotal, COALESCE(sum(july)*${multiplyNum},0) AS julyTotal, COALESCE(sum(august)*${multiplyNum},0) AS augustTotal, COALESCE(sum(september)*${multiplyNum},0) AS septemberTotal, COALESCE(sum(october)*${multiplyNum},0) AS octoberTotal, COALESCE(sum(november)*${multiplyNum},0) AS novemberTotal, COALESCE(sum(december)*${multiplyNum},0) AS decemberTotal FROM ( SELECT metrics,main_id,min(staff_name) AS staffName, SUM ( CASE WHEN month = 1 THEN value ELSE NULL END ) AS january, SUM ( CASE WHEN month = 1 THEN rate ELSE NULL END ) AS januaryRate, SUM ( CASE WHEN month = 2 THEN value ELSE NULL END ) AS february, SUM ( CASE WHEN month = 2 THEN rate ELSE NULL END ) AS februaryRate, SUM ( CASE WHEN month = 3 THEN value ELSE NULL END ) AS march, SUM ( CASE WHEN month = 3 THEN rate ELSE NULL END ) AS marchRate, SUM ( CASE WHEN month = 4 THEN value ELSE NULL END ) AS april, SUM ( CASE WHEN month = 4 THEN rate ELSE NULL END ) AS aprilRate, SUM ( CASE WHEN month = 5 THEN value ELSE NULL END ) AS may, SUM ( CASE WHEN month = 5 THEN rate ELSE NULL END ) AS mayRate, SUM ( CASE WHEN month = 6 THEN value ELSE NULL END ) AS june, SUM ( CASE WHEN month = 6 THEN rate ELSE NULL END ) AS juneRate, SUM ( CASE WHEN month = 7 THEN value ELSE NULL END ) AS july, SUM ( CASE WHEN month = 7 THEN rate ELSE NULL END ) AS julyRate, SUM ( CASE WHEN month = 8 THEN value ELSE NULL END ) AS august, SUM ( CASE WHEN month = 8 THEN rate ELSE NULL END ) AS augustRate, SUM ( CASE WHEN month = 9 THEN value ELSE NULL END ) AS september, SUM ( CASE WHEN month = 9 THEN rate ELSE NULL END ) AS septemberRate, SUM ( CASE WHEN month = 10 THEN value ELSE NULL END ) AS october, SUM ( CASE WHEN month = 10 THEN rate ELSE NULL END ) AS octoberRate, SUM ( CASE WHEN month = 11 THEN value ELSE NULL END ) AS november, SUM ( CASE WHEN month = 11 THEN rate ELSE NULL END ) AS novemberRate, SUM ( CASE WHEN month = 12 THEN value ELSE NULL END ) AS december, SUM ( CASE WHEN month = 12 THEN value ELSE NULL END ) AS decemberRate FROM bi_target_new_product_setting WHERE metrics=#{params.metrics} AND is_deleted = FALSE GROUP BY metrics,main_id ) temp LEFT JOIN bi_target_year ty ON temp.main_id = ty.id WHERE ty.is_deleted=false
AND ty.year =#{params.year}
AND ty.dept_id =#{params.deptId}
AND temp.staffName ILIKE concat('%', #{params.name}::text ,'%')
${params.permissionSql}
